// ============================================================
// sw.js — SchoolOS+ PWA Service Worker (Cache Only)
// ============================================================
// This SW handles ONLY offline caching for the PWA app shell.
// Firebase Cloud Messaging (background push) is handled separately
// by /firebase-messaging-sw.js (auto-generated by vite.config.js).
// ============================================================

const CACHE_NAME = 'schoolos-pwa-v4';
const ASSETS_TO_PRECACHE = [
  '/',
  '/index.html',
  '/manifest.webmanifest',
  '/theme-init.js',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
];

// Install: pre-cache the app shell
self.addEventListener('install', (event) => {
  self.skipWaiting(); // Activate immediately — don't wait for old SW to die
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      console.log('[sw.js] Pre-caching app shell assets');
      return cache.addAll(ASSETS_TO_PRECACHE);
    })
  );
});

// Activate: delete old caches and claim all clients immediately
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((cacheNames) =>
        Promise.all(
          cacheNames
            .filter((name) => name !== CACHE_NAME)
            .map((name) => {
              console.log('[sw.js] Deleting old cache:', name);
              return caches.delete(name);
            })
        )
      )
      .then(() => self.clients.claim())
  );
});

// Fetch strategy:
//  - Navigation (HTML): Network-first, fallback to cached index.html (SPA)
//  - Hashed assets (/assets/*): Cache-first (they never change)
//  - Everything else: Network-first, no caching
self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);

  // Only handle same-origin GET requests
  if (request.method !== 'GET' || url.origin !== self.location.origin) return;

  // Never intercept SW files themselves
  if (
    url.pathname.startsWith('/sw.js') ||
    url.pathname.startsWith('/firebase-messaging-sw.js')
  ) return;

  // Navigation (SPA fallback)
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request).catch(() => caches.match('/index.html'))
    );
    return;
  }

  // Hashed Vite build assets — safe to cache indefinitely
  if (url.pathname.startsWith('/assets/')) {
    event.respondWith(
      caches.match(request).then((cached) => {
        if (cached) return cached;
        return fetch(request).then((response) => {
          if (
            response &&
            response.status === 200 &&
            (response.type === 'basic' || response.type === 'cors')
          ) {
            const toCache = response.clone();
            caches.open(CACHE_NAME).then((cache) => cache.put(request, toCache));
          }
          return response;
        });
      })
    );
    return;
  }

  // Static public assets (icons, fonts, images)
  const isStaticAsset =
    url.pathname.endsWith('.png') ||
    url.pathname.endsWith('.ico') ||
    url.pathname.endsWith('.webp') ||
    url.pathname.endsWith('.woff2') ||
    url.pathname.endsWith('.woff');

  if (isStaticAsset) {
    event.respondWith(
      caches.match(request).then((cached) => cached || fetch(request))
    );
    return;
  }

  // Default: network only (API calls, Supabase, etc.)
  // No caching — let them fail naturally if offline
});
